$not_ordered = 0;
$in_flight = 0;
$recent = array();
foreach ( $orders as $order ) {
	$groups = function_exists( 'homeglo_fulfilment_order_groups' ) ? homeglo_fulfilment_order_groups( $order ) : array();
	if ( ! $groups ) { continue; }
	$open_orders++;
	if ( count( $recent ) < 6 ) { $recent[] = array( 'order' => $order, 'groups' => $groups ); }
	foreach ( $groups as $group ) {
		if ( 'not_ordered' === $group['status'] ) { $not_ordered++; }
		if ( in_array( $group['status'], array( 'ordered', 'processing', 'shipped' ), true ) ) { $in_flight++; }
	}
}
$products = function_exists( 'wc_get_products' ) ? wc_get_products( array( 'limit' => -1, 'status' => array( 'publish', 'draft', 'private' ), 'return' => 'ids' ) ) : array();
	$customer_counts = count_users();
	$customer_total = isset( $customer_counts['avail_roles']['customer'] ) ? (int) $customer_counts['avail_roles']['customer'] : 0;
?>
<section class="hg-manager-page-head">
	<div><p>HOMEGLO MANAGEMENT</p><h1>Good to see you.</h1><span>Everything the manager needs, without WordPress.</span></div>
	<div class="hg-manager-head-actions"><?php if ( homeglo_manager_can( 'orders', $manager ) ) : ?><a class="hg-manager-primary is-light" href="<?php echo esc_url( homeglo_manager_url( 'orders' ) ); ?>">Open orders</a><?php endif; ?><?php if ( homeglo_manager_can( 'add_product', $manager ) ) : ?><a class="hg-manager-primary" href="<?php echo esc_url( homeglo_manager_url( 'add-product' ) ); ?>">Add product <span>＋</span></a><?php endif; ?></div>
</section>
<?php if ( ! empty( $_GET['denied'] ) ) : ?><div class="hg-manager-alert is-error">You do not have permission to open that HomeGlo area. Ask an Admin/Owner if you need access.</div><?php endif; ?>
<div class="hg-manager-stats">
	<?php if ( homeglo_manager_can( 'orders', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'orders' ) ); ?>"><span>Open dropship orders</span><strong><?php echo esc_html( $open_orders ); ?></strong><small>Orders with supplier-linked products</small></a><?php endif; ?>
	<?php if ( homeglo_manager_can( 'orders', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'orders' ) ); ?>"><span>Need supplier order</span><strong><?php echo esc_html( $not_ordered ); ?></strong><small>Place these with the supplier</small></a><?php endif; ?>
	<?php if ( homeglo_manager_can( 'orders', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'orders' ) ); ?>"><span>In fulfilment</span><strong><?php echo esc_html( $in_flight ); ?></strong><small>Ordered, processing or shipped</small></a><?php endif; ?>
	<?php if ( homeglo_manager_can( 'products', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'products' ) ); ?>"><span>Products</span><strong><?php echo esc_html( count( $products ) ); ?></strong><small>HomeGlo catalogue</small></a><?php endif; ?>
</div>

<section class="hg-manager-panel">
	<div class="hg-manager-quick-actions">
			<?php if ( homeglo_manager_can( 'add_product', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'add-product' ) ); ?>"><span>＋</span><strong>Add product</strong><small>Create simple or variable products</small></a><?php endif; ?>
			<?php if ( homeglo_manager_can( 'products', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'products' ) ); ?>"><span>◇</span><strong>Products</strong><small>Catalogue, prices and stock</small></a><?php endif; ?>
			<?php if ( homeglo_manager_can( 'customers', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'customers' ) ); ?>"><span>◎</span><strong>Customers</strong><small><?php echo esc_html( $customer_total ); ?> registered accounts</small></a><?php endif; ?>
			<?php if ( homeglo_manager_can( 'orders', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'orders' ) ); ?>"><span>□</span><strong>Orders</strong><small>Process and fulfil orders</small></a><?php endif; ?>
		</div>
		<div class="hg-manager-panel-head"><div><p><?php echo homeglo_manager_can( 'orders', $manager ) ? 'RECENT' : 'ACCESS'; ?></p><h2><?php echo homeglo_manager_can( 'orders', $manager ) ? 'Orders to manage' : 'Your permitted areas'; ?></h2></div><?php if ( homeglo_manager_can( 'orders', $manager ) ) : ?><a href="<?php echo esc_url( homeglo_manager_url( 'orders' ) ); ?>">View all →</a><?php endif; ?></div>
	<?php if ( ! homeglo_manager_can( 'orders', $manager ) ) : ?>
			<div class="hg-manager-empty"><strong>Limited access</strong><span>Your Admin controls which HomeGlo areas are available to this account.</span></div>
		<?php elseif ( ! $recent ) : ?>
		<div class="hg-manager-empty"><strong>No supplier orders yet</strong><span>Supplier-linked customer orders will appear here.</span></div>
	<?php else : ?>
		<div class="hg-manager-order-list">
			<?php foreach ( $recent as $entry ) :
				$order = $entry['order'];
				$customer = trim( $order->get_formatted_billing_full_name() );
				$customer = $customer ? $customer : 'Guest customer';
				$needs = 0;
				foreach ( $entry['groups'] as $group ) { if ( 'not_ordered' === $group['status'] ) { $needs++; } }
				?>
				<a href="<?php echo esc_url( homeglo_manager_url( 'orders', array( 'order' => $order->get_id() ) ) ); ?>">
					<span class="hg-manager-order-id">#<?php echo esc_html( $order->get_order_number() ); ?></span>
					<span><strong><?php echo esc_html( $customer ); ?></strong><small><?php echo esc_html( $order->get_date_created() ? $order->get_date_created()->date_i18n( 'j M, g:i a' ) : '' ); ?></small></span>
					<span class="hg-manager-order-status"><?php echo $needs ? esc_html( $needs . ' supplier order' . ( $needs > 1 ? 's' : '' ) . ' needed' ) : 'In progress'; ?></span>
					<strong><?php echo wp_kses_post( $order->get_formatted_order_total() ); ?></strong>
					<i>→</i>
